  // ── trails ───────────────────────────────────────────────────────────────
  man_tr_h_cammini: { IT: '🥾 Cammini storici', EN: '🥾 Historic trails', FR: '🥾 Chemins historiques', ES: '🥾 Caminos históricos', DE: '🥾 Historische Pilgerwege', RU: '🥾 Исторические пути', ZH: '🥾 历史古道' },
